import { ComponentProps, ReactElement, ReactNode } from 'react';

import { IconName } from '@swo/icon';

import { useTabs } from '../context/Tabs.Context';
import { Tab } from './tab/Tab';

export interface TabItemProps {
  id: string;
  title?: string;
  isDisabled?: boolean;
  count?: number;
  children?: ReactNode;

  icon?: IconName;
}

export function TabItem({ id, title, isDisabled, count, icon }: TabItemProps) {
  const { selectedTab, onTabChange, position } = useTabs();

  return (
    <Tab
      title={title}
      isSelected={id === selectedTab}
      isDisabled={isDisabled}
      count={count}
      onClick={() => onTabChange(id)}
      testId={`tab-${id}`}
      position={position}
      icon={icon}
    />
  );
}
TabItem.displayName = 'Tab';

export function isTabItem(tabItem: ReactElement): tabItem is ReactElement<ComponentProps<typeof TabItem>> {
  if (!tabItem) {
    return false;
  }
  return (tabItem.type as React.FunctionComponent).displayName === 'Tab';
}
