export type IconName = (typeof iconNames)[number];

export interface BasicIconProps {
  name: IconName;
  type?: keyof IconType;
  boxWidth?: number;
  boxHeight?: number;
  color?: string;
  transform?: string;
  className?: string;
  /**
   * @deprecated Use the `color` prop instead. When `gradient` is `true` and no `color` is provided,
   * the icon will be rendered with `var(--brand-primary)` color. The gradient prop will be removed in a future major version.
   */
  gradient?: boolean;
}

export interface AssymetricalIconProps extends BasicIconProps {
  width?: number;
  height?: number;
  size?: never;
}

export interface SymetricalIconProps extends BasicIconProps {
  size?: number;
  width?: never;
  height?: never;
}

export type IconProps = AssymetricalIconProps | SymetricalIconProps;

interface IconData {
  iconPath: ReactElement;
  viewBox: string | undefined;
}

const cache = new Map<string, Promise<IconData>>();

function getKey(name: string, type: keyof IconType) {
  return `${name}__${type}`;
}

export function prefetchIcon(name: string, type: keyof IconType = 'outlined') {
  const key = getKey(name, type);
  if (cache.has(key)) {
    return;
  }

  const res = getIcon(name, type).catch(() => {
    cache.delete(key);
    return { iconPath: <svg></svg>, viewBox: undefined } as IconData;
  });
  cache.set(key, res);
}

function getIcon(name: string, type: keyof IconType): Promise<IconData> {
  const key = getKey(name, type);
  if (!cache.has(key)) {
    const res = import(`./icon-paths/${name}.tsx`).then(
      module => {
        const iconPath = module[name][type] as ReactElement;
        return { iconPath, viewBox: module[name].viewBox as string | undefined } as IconData;
      },
      err => {
        cache.delete(key);
        throw err;
      }
    );
    cache.set(key, res);
  }
  return cache.get(key) as Promise<IconData>;
}

export const Icon = ({
  name,
  type = 'outlined',
  width,
  height,
  size,
  boxWidth = 24,
  boxHeight = 24,
  color = 'currentColor',
  transform = '',
  className = '',
  // eslint-disable-next-line @typescript-eslint/no-deprecated
  gradient = false,
}: IconProps): ReactElement | null => {
  if (size !== undefined) {
    width = size;
    height = size;
  } else {
    width = width ?? 24;
    height = height ?? 24;
  }

  const hasWarnedGradient = useRef(false);

  useEffect(() => {
    if (gradient && !hasWarnedGradient.current) {
      hasWarnedGradient.current = true;
      console.warn(
        `[Icon] The "gradient" prop is deprecated and will be removed in a future major version. ` +
          `Use the "color" prop instead. Example: <Icon name="${name}" color="var(--brand-primary)" />`
      );
    }
  }, [gradient, name]);

  const resolvedColor = gradient && color === 'currentColor' ? 'var(--brand-primary)' : color;

  const [iconContent, setIconContent] = useState<ReactElement>();
  const [viewBox, setViewBox] = useState<string>(`0 0 ${boxWidth} ${boxHeight}`);

  useEffect(() => setViewBox(`0 0 ${boxWidth} ${boxHeight}`), [boxHeight, boxWidth]);

  useEffect(() => {
    if (!name) {
      return;
    }

    getIcon(name, type)
      .then(({ iconPath, viewBox }) => {
        setIconContent(iconPath);
        if (viewBox) {
          setViewBox(viewBox);
        }
      })
      .catch(error => {
        console.error(`Error loading icon: ${name}`, error);
      });
  }, [name, type]);

  return useMemo(() => {
    if (!iconContent) {
      return null;
    }

    return (
      <svg
        className={className}
        data-testid={`svg-${name}`}
        width={width}
        height={height}
        viewBox={viewBox}
        fill={resolvedColor}
        transform={transform}
        xmlns='http://www.w3.org/2000/svg'
      >
        {iconContent}
      </svg>
    );
  }, [iconContent, resolvedColor, name, className, width, height, viewBox, transform]);
};
