import styles from './Popover.module.scss';

import React, { ReactElement, ReactNode } from 'react';

import { usePopover } from './Popover.Context';

interface PopoverTargetProps {
  children: ReactNode;
}

export function PopoverTarget({ children }: PopoverTargetProps) {
  return <>{children}</>;
}

PopoverTarget.displayName = 'Popover.Target';

interface PopoverInternalTargetProps {
  children: ReactElement;
}

export const PopoverInternalTarget = React.forwardRef(({ children }: PopoverInternalTargetProps, ref: React.Ref<HTMLDivElement>) => {
  const { testId } = usePopover();
  return (
    <div className={styles['popover__target']} ref={ref} data-testid={testId + '__target'}>
      {children}
    </div>
  );
});
