import { useCallback, useEffect, useState } from 'react';

const isLetterOrNumberOrSpace = /^[a-z0-9\s]$/i;

const TYPING_TIMEOUT_MS = 1000;

/**
 * A hook to handle keyboard search on a dropdown.
 *
 * Expects that the target element is focusable and will have the focus when the keyboard event is triggered.
 * @param target target element. Element that has triggered the dropdown to open/close
 * @param onSearch callback function to be called when a search is triggered (anytime the typed text changes within a timeframe)
 */
export function useHandleKeyboardSearch(
  target: React.RefObject<HTMLElement | null>,
  onSearch: (text: string) => void,
  isToUseCustomSearch: boolean
) {
  const [typed, setTyped] = useState('');
  const [timeoutId, setTimeoutId] = useState<ReturnType<typeof setTimeout>>();

  const onKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (timeoutId) {
        clearTimeout(timeoutId);
        setTimeoutId(undefined);
      }

      if (isLetterOrNumberOrSpace.test(e.key)) {
        const newTyped = typed + e.key.toLowerCase();
        setTyped(newTyped);
        onSearch(newTyped);

        const newTimeoutId = setTimeout(() => setTyped(''), TYPING_TIMEOUT_MS);
        setTimeoutId(newTimeoutId);

        return;
      } else {
        setTyped('');
      }
    },
    [onSearch, timeoutId, typed]
  );

  useEffect(() => {
    if (isToUseCustomSearch) {
      return;
    }

    const tgt = target?.current;
    tgt?.addEventListener('keydown', onKeyDown);
    return () => {
      tgt?.removeEventListener('keydown', onKeyDown);
    };
  }, [isToUseCustomSearch, onKeyDown, target]);
}
