import styles from './Tabs.module.scss';

import React, { Children, ComponentProps, ReactElement, useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { TabActions, TabActionsPanel } from './components/Tab.Actions';
import { TabContent, TabContentPanel } from './components/Tab.Content';
import { TabDivider } from './components/Tab.Divider';
import { TabDropdown } from './components/Tab.Dropdown';
import { TabItem, isTabItem } from './components/Tab.Item';
import { TabsContext } from './context/Tabs.Context';
import { useInnerSize } from './hooks/useInnerSize';

interface TabsInitialProps {
  testId?: string;
  children: React.ReactNode;
  type?: 'inline' | 'block';
  className?: string;
  position?: 'top' | 'bottom';
}

interface TabsWithSelection extends TabsInitialProps {
  selectedTabId: string;
  onTabChange: (id: string) => void;
}

interface TabsWithoutSelection extends TabsInitialProps {
  selectedTabId?: never;
  onTabChange?: never;
}

export type TabsProps = TabsWithSelection | TabsWithoutSelection;

export function Tabs({
  type = 'block',
  className,
  selectedTabId,
  onTabChange,
  testId = 'tabs',
  position = 'top',
  children,
}: TabsProps): ReactElement {
  const containerRef = useRef<HTMLDivElement>(null);
  const tabRefs = useRef<(HTMLDivElement | null)[]>([]);
  const tabsNavItemsRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const { width: containerInnerWidth } = useInnerSize(containerRef);
  const [actionsWidth, setActionsWidth] = useState(0);
  const tabItems = useMemo(
    () => Children.toArray(children).filter(React.isValidElement) as ReactElement<ComponentProps<typeof TabItem | typeof TabDivider>>[],
    [children]
  );

  const tabItemsWithRef = useMemo(
    () =>
      tabItems.map((child, index) => (
        <div
          ref={el => {
            if (el) {
              tabRefs.current[index] = el;
            }
          }}
          key={`tab-wrapper-${index}`}
        >
          {child}
        </div>
      )) as ReactElement[],
    [tabItems]
  );

  const [stateSelectedTab, setStateSelectedTab] = useState(isTabItem(tabItems[0]) ? tabItems[0].props.id : undefined);
  const [visibleTabs, setVisibleTabs] = useState<ReactElement[]>(tabItems);
  const [overflowTabs, setOverflowTabs] = useState<ReactElement[]>([]);

  const getItemsGap = useCallback(() => {
    const defaultGap = 0;
    if (!tabsNavItemsRef.current) {
      return defaultGap;
    }
    const style = window.getComputedStyle(tabsNavItemsRef.current);
    return parseFloat(style.gap) || defaultGap;
  }, [tabsNavItemsRef]);

  const measureTabs = useCallback(() => {
    const containerWidth = containerInnerWidth;
    const dropdownWidth = dropdownRef.current?.offsetWidth || 0;
    let usedWidth = 0;
    const visible: ReactElement[] = [];
    const overflow: ReactElement[] = [];
    const itemsGap = getItemsGap();
    tabItems.forEach((tab, index) => {
      const tabEl = tabRefs.current[index];
      if (!tabEl) {
        return;
      }

      const width = tabEl.offsetWidth;
      if (usedWidth + width + itemsGap <= containerWidth - actionsWidth) {
        visible.push(tab);
        usedWidth = usedWidth + width + itemsGap;
      } else {
        overflow.push(tab);
      }
    });

    if (overflow.length > 0) {
      while (visible.length > 0 && usedWidth + dropdownWidth > containerWidth - actionsWidth) {
        const last = visible.pop();
        const lastEl = tabRefs.current[visible.length];
        const lastWidth = (lastEl?.offsetWidth || 0) + itemsGap;
        if (last) {
          overflow.unshift(last);
        }
        usedWidth -= lastWidth;
      }
    }

    setVisibleTabs(visible);
    setOverflowTabs(overflow);
  }, [tabItems, containerInnerWidth, getItemsGap, actionsWidth]);

  useEffect(() => {
    measureTabs();
  }, [measureTabs, selectedTabId, stateSelectedTab, actionsWidth]);

  const handleTabChange = useCallback((id: string) => (onTabChange ? onTabChange(id) : setStateSelectedTab(id)), [onTabChange]);

  const handleActionsTabLoad = useCallback((size: number) => {
    setActionsWidth(size);
  }, []);

  const classNameStr = useMemo(
    () => [styles['tabs-nav'], styles[`tabs-nav--${type}`], styles[`tabs-nav--${position}`], className].filter(Boolean).join(' '),
    [className, type, position]
  );

  if (!tabItems?.length) {
    return <>''</>;
  }

  const tabsNavigation = (
    <div className={classNameStr} data-testid='tabs-nav' ref={containerRef}>
      <div className={`${styles['tabs-nav__items']} ${styles['tabs-nav__invisible']}`}>{tabItemsWithRef}</div>
      <div className={styles['tabs-nav__items']} data-testid='tabs-nav__items' ref={tabsNavItemsRef}>
        {visibleTabs}
        <div
          ref={dropdownRef}
          className={overflowTabs.length === 0 ? styles['tabs-nav__invisible'] : ''}
          data-testid='tabs-nav__dropdown-wrapper'
        >
          <TabDropdown tabItems={overflowTabs} />
        </div>
      </div>
      <TabActionsPanel tabItems={tabItems} onLoad={handleActionsTabLoad} />
    </div>
  );

  const tabsContent = <TabContentPanel tabItems={tabItems} type={type} />;

  return (
    <TabsContext.Provider
      value={{
        selectedTab: selectedTabId ?? stateSelectedTab,
        onTabChange: handleTabChange,
        position,
      }}
    >
      <div data-testid={testId} className={`${styles[`tabs-container`]} ${styles[`tabs-container--${position}`]}`}>
        {tabsNavigation}
        {tabsContent}
      </div>
    </TabsContext.Provider>
  );
}

export const Tab = Object.assign(TabItem, {
  Content: TabContent,
  Actions: TabActions,
  Divider: TabDivider,
});
