import { AbsolutePosition, CssPosition, CustomRelativePosition } from '../models';

export function calculatePosition(
  target: AbsolutePosition,
  popoverHeight: number,
  popoverWidth: number,
  positions: Required<CustomRelativePosition>[],
  cssPosition: CssPosition
) {
  const windowHeight = window.innerHeight;
  const windowWidth = window.innerWidth;

  const processedPositions = positions.map(({ position, offset, flick }) => {
    const isPositionAtTop = position === 'top' || position === 'top-start' || position === 'top-end';
    const isPositionAtBottom = position === 'bottom' || position === 'bottom-start' || position === 'bottom-end';
    const isPositionAtLeft = position === 'left' || position === 'left-start' || position === 'left-end';
    const isPositionAtRight = position === 'right' || position === 'right-start' || position === 'right-end';
    const isFlickAtLeftOrRight = flick === 'left' || flick === 'right';
    const isFlickAtTopOrBottom = !(isFlickAtLeftOrRight || flick === 'none');
    const isFixedCssPosition = cssPosition === 'fixed';
    const transforms = [];

    let positionToSetTop =
      isPositionAtTop || position === 'left-start' || position === 'right-start'
        ? 0
        : isPositionAtBottom || position === 'left-end' || position === 'right-end'
          ? target.height
          : target.height / 2;
    positionToSetTop = isFixedCssPosition ? positionToSetTop + target.top : positionToSetTop;
    let positionToSetLeft =
      isPositionAtLeft || position === 'top-start' || position === 'bottom-start'
        ? 0
        : isPositionAtRight || position === 'top-end' || position === 'bottom-end'
          ? target.width
          : target.width / 2;
    positionToSetLeft = isFixedCssPosition ? positionToSetLeft + target.left : positionToSetLeft;
    const translateX =
      isPositionAtLeft || position === 'top-end' || position === 'bottom-end'
        ? 'translateX(-100%)'
        : isPositionAtRight || position === 'top-start' || position === 'bottom-start'
          ? ''
          : 'translateX(-50%)';
    const translateY =
      isPositionAtTop || position === 'left-end' || position === 'right-end'
        ? 'translateY(-100%)'
        : isPositionAtBottom || position === 'left-start' || position === 'right-start'
          ? ''
          : 'translateY(-50%)';
    const offsetXDirection = isPositionAtLeft ? -1 : isPositionAtRight ? 1 : 0;
    const offsetYDirection = isPositionAtTop ? -1 : isPositionAtBottom ? 1 : 0;

    if (translateX) {
      transforms.push(translateX);
    }
    if (translateY) {
      transforms.push(translateY);
    }

    const top = positionToSetTop + offsetYDirection * (offset.y + (isFlickAtTopOrBottom ? 8 : 0));
    const left = positionToSetLeft + offsetXDirection * (offset.x + (isFlickAtLeftOrRight ? 8 : 0));

    const absoluteTop =
      top +
      (isPositionAtTop || position === 'left-end' || position === 'right-end'
        ? -popoverHeight
        : isPositionAtBottom || position === 'left-start' || position === 'right-start'
          ? 0
          : -popoverHeight / 2) +
      (isFixedCssPosition ? 0 : target.top);
    const absoluteBottom = absoluteTop + popoverHeight;
    const absoluteLeft =
      left +
      (isPositionAtLeft || position === 'top-end' || position === 'bottom-end'
        ? -popoverWidth
        : isPositionAtRight || position === 'top-start' || position === 'bottom-start'
          ? 0
          : -popoverWidth / 2) +
      (isFixedCssPosition ? 0 : target.left);
    const absoluteRight = absoluteLeft + popoverWidth;

    const bottomValidDistance = windowHeight - absoluteBottom > 0 ? 0 : windowHeight - absoluteBottom;
    const topValidDistance = absoluteTop > 0 ? 0 : absoluteTop;
    const rightValidDistance = windowWidth - absoluteRight > 0 ? 0 : windowWidth - absoluteRight;
    const leftValidDistance = absoluteLeft > 0 ? 0 : absoluteLeft;
    return {
      top: top + 'px',
      left: left + 'px',
      transform: transforms.join(' '),
      yValidDistance: bottomValidDistance + topValidDistance,
      yValidDistanceDirection: bottomValidDistance > topValidDistance ? -1 : 1,
      xValidDistance: rightValidDistance + leftValidDistance,
      xValidDistanceDirection: rightValidDistance > leftValidDistance ? -1 : 1,
    };
  });

  const validPositions = processedPositions.filter(({ xValidDistance, yValidDistance }) => xValidDistance >= 0 && yValidDistance >= 0);
  if (validPositions.length > 0) {
    const stylePosition = validPositions[0];
    return { stylePosition, relativePosition: positions[processedPositions.indexOf(stylePosition)] };
  }

  const semiValidPositions = processedPositions.filter(({ xValidDistance, yValidDistance }) => xValidDistance >= 0 || yValidDistance >= 0);
  if (semiValidPositions.length > 0) {
    const stylePosition = semiValidPositions.reduce(
      (selected, item) =>
        selected.xValidDistance + selected.yValidDistance >= item.xValidDistance + item.yValidDistance ? selected : item,
      semiValidPositions[0]
    );

    // Use the best position and move the popover to fit in the screen
    const top = parseFloat(stylePosition.top);
    const left = parseFloat(stylePosition.left);
    if (stylePosition.yValidDistance < 0) {
      stylePosition.top = top + stylePosition.yValidDistanceDirection * stylePosition.yValidDistance + 'px';
    }
    if (stylePosition.xValidDistance < 0) {
      stylePosition.left = left + stylePosition.xValidDistanceDirection * stylePosition.xValidDistance + 'px';
    }

    return { stylePosition, relativePosition: positions[processedPositions.indexOf(stylePosition)] };
  }

  return { stylePosition: processedPositions[0], relativePosition: positions[0] };
}
