import { FlatNamespace, KeyPrefix } from 'i18next';
import { useMemo } from 'react';
import { FallbackNs, UseTranslationOptions, UseTranslationResponse, useTranslation as useTranslationI18n } from 'react-i18next';
import { $Tuple } from 'react-i18next/helpers';

import { i18n } from '../i18n/translation';

const defaultOptions = { i18n };
export function useTranslation<
  Ns extends FlatNamespace | $Tuple<FlatNamespace> | undefined = undefined,
  KPrefix extends KeyPrefix<FallbackNs<Ns>> = undefined,
>(ns?: Ns, options?: UseTranslationOptions<KPrefix>): UseTranslationResponse<FallbackNs<Ns>, KPrefix> {
  const processedOptions = useMemo(() => ({ ...defaultOptions, ...options }), [options]);
  return useTranslationI18n(ns, processedOptions);
}
