import { useEffect } from 'react';

/**
 * A hook to notify whenever there's a resize event on the document.
 * @param isActive flag to indicate if the scroll listener should be active or not
 * @param onResize callback to be called when any resize happens
 */
export function useOnResize(isActive: boolean, onResize: () => void) {
  useEffect(() => {
    if (!isActive) {
      return;
    }
    window.addEventListener('resize', onResize, true);

    return () => window.removeEventListener('resize', onResize, true);
  }, [isActive, onResize]);
}
