import { resolveDateFormatForLanguage } from './dateFormatMapping';
import { getNumberSeparators } from './numberFormat';

export interface BrowserEnvironment {
  languageCode: string;
  timeZone: string;
  dateFormat: string;
  timeFormat: '12h' | '24h';
  numberFormat: { decimalSeparator: string; groupSeparator: string };
}

let cache: BrowserEnvironment | null = null;

export function _resetCache() {
  cache = null;
}

export function detectBrowserEnvironment(): BrowserEnvironment {
  if (cache) {
    return cache;
  }
  const languageCode = navigator.language || navigator.languages?.[0] || 'en-US';
  const dateFormat = resolveDateFormatForLanguage(languageCode);
  const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const timeFormat = new Intl.DateTimeFormat(languageCode, { hour: 'numeric' }).formatToParts(new Date()).some(p => p.type === 'dayPeriod')
    ? '12h'
    : '24h';
  const numberFormat = getNumberSeparators(languageCode);
  cache = { languageCode, timeZone, dateFormat, timeFormat, numberFormat };
  return cache;
}

export function getBrowserDefaults(): BrowserEnvironment {
  return detectBrowserEnvironment();
}
