import styles from './tab/Tab.module.scss';

import { Children, ReactElement, isValidElement, useMemo } from 'react';

import { Dropdown, ListOption, useDropdownSelect } from '@swo/dropdown';
import { Icon } from '@swo/icon';
import { useTranslation } from '@swo/utils';

import { useTabs } from '../context/Tabs.Context';
import { isTabItem } from './Tab.Item';

interface TabDropdownProps {
  tabItems: ReactElement[];
}

function tabToListOption(tabItem: ReactElement) {
  if (!isTabItem(tabItem)) {
    return {
      type: 'divider',
    };
  }
  return { label: tabItem.props.title, value: tabItem.props.id, isDisabled: tabItem.props.isDisabled };
}

export function TabDropdown({ tabItems }: TabDropdownProps) {
  const { selectedTab, onTabChange, position } = useTabs();

  const actions: ListOption[] = useMemo(() => {
    const allOptions = Children.toArray(tabItems)
      .map(child => isValidElement(child) && tabToListOption(child))
      .filter(Boolean) as ListOption[];

    const filteredOptions = allOptions.reduce<ListOption[]>((acc, option, index, arr) => {
      if ('type' in option && option.type === 'divider') {
        const isFirstItem = index === 0;
        const isLastItem = index === arr.length - 1;

        if (!isFirstItem && !isLastItem) {
          acc.push(option);
        }
      } else {
        acc.push(option);
      }

      return acc;
    }, []);
    return filteredOptions;
  }, [tabItems]);

  const isSelected = useMemo(() => {
    return actions.some(action => 'value' in action && action.value === selectedTab);
  }, [actions, selectedTab]);

  const props = useDropdownSelect(selectedTab, actions, onTabChange);
  const { t } = useTranslation();
  return (
    <div
      className={`${styles['tab-wrapper']} ${styles[`tab-wrapper--${position}`]} ${isSelected ? `${styles[`tab__active`]} ${styles[`tab__active--${position}`]}` : ''}`}
      data-testid='tabs-nav__dropdown'
    >
      <Dropdown {...props} popoverCssPosition='fixed'>
        <span className={styles['tab']}>
          {t('tabs.dropdown.more')} <Icon name='arrow_down_keyboard' />
        </span>
      </Dropdown>
    </div>
  );
}
