import { useCallback } from 'react';

import { DropdownListProps } from '../Dropdown';
import { ListItem, ListOption } from '../types';

/**
 * Hook to setup a dropdown containing only actions. It won't require or track selected items.
 * @param options list of actions to display on the dropdown menu
 * @param onSelected callback function to be called when an action is selected
 * @returns
 */
export function useDropdownMenu<T>(
  options: ListOption<T>[],
  onSelected: (value: T) => void
): Omit<DropdownListProps<T>, 'children'> & { selectedItem?: ListItem<T> } {
  const onItemSelected = useCallback((value: T) => onSelected(value), [onSelected]);

  return {
    options,
    value: [],
    onItemSelected,
  };
}
