import styles from '../Dropdown.module.scss';

import React, { useCallback, useEffect, useMemo, useRef } from 'react';

import { Icon, prefetchIcon } from '@swo/icon';

import { DropdownListOptionProps, ListItem } from '../types';

prefetchIcon('check');

export function DropdownOptionSingleOption<T>({
  option,
  selectedValue,
  activeValue,
  onSelect,
  onHover,
  children,
  isKeyboardMode,
}: DropdownListOptionProps<T>) {
  if ('type' in option) {
    if (option.type === 'divider') {
      return <li className={styles['dropdown-list__divider']}></li>;
    }
    return <li className={styles['dropdown-list__group']}>{children ? children : (option.optionLabel ?? option.label)}</li>;
  }
  return (
    <DropdownOptionSingleItem
      selectedValue={selectedValue}
      activeValue={activeValue}
      option={option}
      onSelect={onSelect}
      onHover={onHover}
      isKeyboardMode={isKeyboardMode}
    >
      {children}
    </DropdownOptionSingleItem>
  );
}

interface DropdownOptionSingleItemProps<T> {
  selectedValue: T[];
  activeValue: T | null;
  option: ListItem<T>;
  onSelect: (option: ListItem<T>) => void;
  onHover: (option: ListItem<T>) => void;
  isKeyboardMode: boolean | undefined;
  children?: React.ReactNode;
}

export function DropdownOptionSingleItem<T>({
  selectedValue,
  activeValue,
  option,
  onSelect,
  onHover,
  children,
  isKeyboardMode,
}: DropdownOptionSingleItemProps<T>) {
  const isDisabled = option.isDisabled;
  const isSelected = selectedValue.includes(option.value);
  const onClick = useCallback(() => (!isDisabled ? onSelect(option) : null), [isDisabled, onSelect, option]);
  const onMouseEnter = useCallback(() => onHover(option), [onHover, option]);
  const elRef = useRef<HTMLLIElement>(null);
  const { className, ...liProps } = option.props ?? {};
  const isActive = activeValue === option.value;

  useEffect(() => {
    if (!isActive || !elRef.current) {
      return;
    }

    if (isElementVisible(elRef.current, elRef.current.parentElement as HTMLElement)) {
      return;
    }
    elRef.current.scrollIntoView({ block: 'nearest' });
  }, [isActive]);

  const processedClassName = useMemo(() => {
    const classes = [styles['dropdown-list__item']];

    if (isActive && isKeyboardMode) {
      classes.push(styles['dropdown-list__item--active']);
    }
    if (isSelected) {
      classes.push(styles['dropdown-list__item--selected']);
    }
    if (isDisabled) {
      classes.push(styles['dropdown-list__item--disabled']);
    }
    if (className) {
      classes.push(className);
    }
    return classes.join(' ');
  }, [isActive, isSelected, isDisabled, className, isKeyboardMode]);

  return (
    <li
      role='option'
      aria-disabled={isDisabled}
      aria-selected={isSelected}
      ref={elRef}
      className={processedClassName}
      {...liProps}
      tabIndex={-1}
      onClick={onClick}
      onMouseEnter={onMouseEnter}
    >
      <span>{children ? children : (option.optionLabel ?? option.label)}</span>{' '}
      {isSelected && !isDisabled && <Icon name='check' height={16} width={16} />}
    </li>
  );
}

function isElementVisible(el: HTMLElement, container: HTMLElement) {
  container = container || document.body;
  const { top, bottom } = el.getBoundingClientRect();
  const containerRect = container.getBoundingClientRect();

  return top <= containerRect.top ? containerRect.top <= top : bottom <= containerRect.bottom;
}
