import styles from '../Tabs.module.scss';

import { Children, ReactElement, ReactNode, isValidElement, useEffect, useMemo, useRef } from 'react';

import { isButton } from '@swo/button';

import { useTabs } from '../context/Tabs.Context';
import { TabActionDropdown } from './Tab.Actions.Dropdown';
import { isTabItem } from './Tab.Item';

export interface TabActionsProps {
  children: ReactNode;
}

export function TabActions({ children }: TabActionsProps) {
  return <>{children}</>;
}

TabActions.displayName = 'Tab.Actions';

function isTabActions(el: ReactElement): el is ReactElement<TabActionsProps> {
  return el.type === TabActions;
}

interface TabActionsPanelProps {
  tabItems: ReactElement[];
  onLoad: (size: number) => void;
}

export function TabActionsPanel({ tabItems, onLoad }: TabActionsPanelProps) {
  const { selectedTab } = useTabs();
  const selectedItem = tabItems.filter(isTabItem).find(item => item.props.id === selectedTab);

  const tabAction = useMemo(() => {
    return selectedItem
      ? Children.toArray(selectedItem.props.children).find(child => isValidElement(child) && isTabActions(child))
      : undefined;
  }, [selectedItem]);

  const [firstButton, ...dropdownButtons] = useMemo(() => {
    return Children.toArray(tabAction?.props.children || [])
      .filter(child => isValidElement(child))
      .filter(isButton);
  }, [tabAction]);

  const tabActionsElements = useMemo(() => {
    return tabItems
      .filter(isTabItem)
      .map(tab => Children.toArray(tab.props.children).find(child => isValidElement(child) && isTabActions(child)))
      .filter(Boolean);
  }, [tabItems]);

  const actionsRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const maxWidth = actionsRefs.current.reduce((max, el) => {
      const w = el?.offsetWidth || 0;
      return w > max ? w : max;
    }, 0);
    onLoad?.(maxWidth);
  }, [tabActionsElements, onLoad]);

  if (!tabActionsElements.length) {
    return null;
  }

  return (
    <>
      <div className={styles['tabs-nav__action-buttons__invisible']}>
        {tabActionsElements.map((action, idx) => (
          <div
            key={idx}
            ref={el => {
              actionsRefs.current[idx] = el;
            }}
          >
            {action}
          </div>
        ))}
      </div>
      <div className={styles['tabs-nav__action-buttons']} data-testid='tabs-nav__action-buttons'>
        {firstButton}
        {dropdownButtons.length > 0 && <TabActionDropdown actionItems={dropdownButtons} />}
      </div>
    </>
  );
}
