export function getNumberSeparators(locale: string): { decimalSeparator: string; groupSeparator: string } {
  let decimalSeparator = '.';
  let groupSeparator = ',';
  try {
    const parts = new Intl.NumberFormat(locale).formatToParts(1234567.89);
    const decimalPart = parts.find(p => p.type === 'decimal');
    const groupPart = parts.find(p => p.type === 'group');
    if (decimalPart) {
      decimalSeparator = decimalPart.value;
    }
    if (groupPart) {
      groupSeparator = groupPart.value;
      const whitespaceVariants = ['\u202F', '\u00A0', '\u2009', '\u2002', '\u2003', '\u2007'];
      if (whitespaceVariants.includes(groupSeparator)) {
        groupSeparator = ' ';
      }
    }
    if (decimalSeparator === groupSeparator) {
      groupSeparator = decimalSeparator === ',' ? '.' : ',';
    }
  } catch {
    // Intentionally left empty: fallback to default separators
  }
  return { decimalSeparator, groupSeparator };
}
