import styles from './Card.module.scss';

import { HTMLAttributes, RefObject, useMemo } from 'react';

interface CardProps extends HTMLAttributes<HTMLDivElement> {
  testId?: string;
  ref?: RefObject<HTMLDivElement | null>;
}

function Card({ className, children, testId = 'card', ref, ...props }: CardProps) {
  const cardClassNames = useMemo(() => [className, styles['card']].filter(Boolean).join(' '), [className]);

  return (
    <div ref={ref} className={cardClassNames} data-testid={testId} {...props}>
      {children}
    </div>
  );
}

export { Card, CardProps };
