import React, { useContext } from 'react';

import { CssPosition, CustomRelativePosition, StylePosition } from './models';

interface PopoverContextProps {
  isOpen: boolean;
  isPositionUpdated: boolean;
  minWidth?: number;
  position: StylePosition;
  cssPosition: CssPosition;
  currentRelativePosition?: Required<CustomRelativePosition>;
  popoverColor: string;
  flickColor: string;
  className?: string;
  testId: string;
}

export const PopoverContext = React.createContext<PopoverContextProps>({} as PopoverContextProps);

export const usePopover = () => {
  const context = useContext(PopoverContext);
  if (!context) {
    throw new Error('usePopover must be used within Popover context provider');
  }
  return context;
};
