import type { Locale } from 'date-fns';
import { format } from 'date-fns/format';
import { PropsWithChildren, createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

import { NO_VALUE } from '../../const';
import { useDesignSystemOptions } from '../../useDesignSystemOptions';
import { detectBrowserEnvironment } from '../helper/browserEnvironment';
import { resolveLocaleFolder } from '../helper/resolveLocaleFolder';
import { LanguageCode, i18n } from '../i18n/translation';
import { FormatCurrencyOptions, useFormatCurrency } from './useFormatCurrency';
import { useFormatDateInternal } from './useFormatDate';
import { FormatNumberOptions, OptionalNumber, useFormatNumber } from './useFormatNumber';
import { formatTimeCore, useFormatTimeInternal } from './useFormatTime';

export interface LocalisationProviderProps extends PropsWithChildren {
  languageCode: LanguageCode;
}

export interface DesignSystemLocalisationData {
  languageCode: LanguageCode;
  locale?: Locale;
  formatCurrency: (value: OptionalNumber, opts?: FormatCurrencyOptions) => string;
  formatNumber: (value: OptionalNumber, opts?: FormatNumberOptions) => string;
  formatDate: (date: string | Date, dateFormat?: string) => string;
  formatTime: (date: string | Date, timeFormat?: string) => string;
  numberFormat: { decimalSeparator: string; groupSeparator: string };
  dateFormat: string;
  timeFormat: '12h' | '24h';
  timeZone: string;
}

const LocalisationContext = createContext<DesignSystemLocalisationData & { isDefault: boolean }>({
  languageCode: 'en-US',
  formatCurrency: (value: OptionalNumber) => value?.toLocaleString() ?? NO_VALUE,
  formatNumber: (value: OptionalNumber) => value?.toLocaleString() ?? NO_VALUE,
  formatDate: (date: string | Date) => format(new Date(date), 'M/d/yyyy'),
  formatTime: (date: string | Date, timeFormat?: string) => formatTimeCore(date, { timeFormat }),
  numberFormat: { decimalSeparator: '.', groupSeparator: ',' },
  dateFormat: 'M/d/yyyy',
  timeFormat: '24h',
  timeZone: 'UTC',
  isDefault: true,
});

export function useLocalisation(): DesignSystemLocalisationData {
  const ctx = useContext(LocalisationContext);
  if (ctx.isDefault) {
    console.warn(
      `[Design System] You are using the 'useLocalisation' hook outside of a DesignSystemOptionsProvider. Please add a DesignSystemOptionsProvider to your application.`
    );
  }
  return ctx;
}

export function LocalisationProvider({ languageCode, children }: LocalisationProviderProps) {
  const env = detectBrowserEnvironment();
  const effectiveLanguage: LanguageCode = (languageCode || env.languageCode) as LanguageCode;
  const { dateFormat: overrideDateFormat, timeFormat: overrideTimeFormat, timeZone: overrideTimeZone } = useDesignSystemOptions();

  const [isLoading, setIsLoading] = useState(true);
  const [locale, setLocale] = useState<Locale>();
  const [error, setError] = useState<unknown>();

  const dateFormat = overrideDateFormat || env.dateFormat;
  const timeFormat: '12h' | '24h' = (overrideTimeFormat ?? env.timeFormat) === '12h' ? '12h' : '24h';
  const timeZone = overrideTimeZone || env.timeZone;

  const formatNumber = useFormatNumber();
  const formatCurrency = useFormatCurrency();
  const formatTimeInternal = useFormatTimeInternal({ timeFormat, timeZone });
  const formatTime = useCallback(
    (date: string | Date, timeFormatOverride?: string) => {
      return formatTimeInternal(date, {
        timeFormat: timeFormatOverride ?? timeFormat,
        timeZone,
      });
    },
    [formatTimeInternal, timeFormat, timeZone]
  );
  const formatDate = useFormatDateInternal({ dateFormat, locale });

  useEffect(() => {
    async function run() {
      try {
        await i18n.changeLanguage(effectiveLanguage);
        const folder = resolveLocaleFolder(effectiveLanguage);
        const loadedLocale = await import(`../date-locales/${folder}/index.ts`);
        setLocale(loadedLocale.default);
      } catch (err) {
        const falbackLocale = await import(`../date-locales/en-GB/index`);
        setLocale(falbackLocale.default);
        console.error(err);
        setError(err);
      } finally {
        setIsLoading(false);
      }
    }
    run();
  }, [effectiveLanguage]);

  const value = useMemo(
    () => ({
      languageCode: effectiveLanguage,
      locale,
      formatNumber,
      formatCurrency,
      formatDate,
      formatTime,
      numberFormat: env.numberFormat,
      dateFormat,
      timeFormat,
      timeZone,
      isDefault: false,
    }),
    [effectiveLanguage, locale, formatNumber, formatCurrency, formatDate, formatTime, env.numberFormat, dateFormat, timeFormat, timeZone]
  );

  if (isLoading) {
    return <> </>;
  }
  if (error) {
    return <>{JSON.stringify(error)}</>;
  }

  return <LocalisationContext.Provider value={value}>{children}</LocalisationContext.Provider>;
}
