import { useEffect } from 'react';

import { PopoverTrigger } from '../models';

export function useTrigger(
  target: React.RefObject<HTMLElement | null> | null | undefined,
  trigger: PopoverTrigger,
  onTrigger: (open?: boolean) => void,
  exclude?: HTMLElement | React.RefObject<HTMLElement | null> | null | undefined
) {
  useEffect(() => {
    if (!target?.current) {
      return;
    }

    const current = target.current;
    if (trigger === 'hover') {
      const onMouseEnter = () => {
        onTrigger(true);
      };
      const onMouseLeave = () => {
        onTrigger(false);
      };

      current.addEventListener('mouseenter', onMouseEnter);
      current.addEventListener('mouseleave', onMouseLeave);

      return () => {
        current.removeEventListener('mouseenter', onMouseEnter);
        current.removeEventListener('mouseleave', onMouseLeave);
      };
    } else if (trigger === 'click' || trigger === 'click-manual') {
      const onClick = (e: MouseEvent) => {
        const el = exclude ? ('current' in exclude ? exclude?.current : exclude) : exclude;
        if (el?.contains(e.target as Node)) {
          return;
        }
        onTrigger();
      };
      current.addEventListener('click', onClick);
      return () => current.removeEventListener('click', onClick);
    }
  }, [trigger, onTrigger, target, exclude]);
}
