import styles from './Popover.module.scss';

import React from 'react';

import { usePopover } from './Popover.Context';
import { CustomRelativePosition } from './models';

interface PopoverContentProps {
  children: React.ReactNode;
}

export function PopoverContent({ children }: PopoverContentProps) {
  return <div>{children}</div>;
}

PopoverContent.displayName = 'Popover.Content';

interface PopoverInternalContentProps {
  children: React.ReactElement;
}

function getFlickClassName(currentRelativePosition?: Required<CustomRelativePosition>) {
  return currentRelativePosition && currentRelativePosition.flick !== 'none'
    ? `popover__content__flick--${currentRelativePosition.flick}`
    : '';
}

export const PopoverInternalContent = React.forwardRef(({ children }: PopoverInternalContentProps, ref: React.Ref<HTMLDivElement>) => {
  const {
    isOpen,
    isPositionUpdated,
    minWidth,
    position,
    cssPosition,
    currentRelativePosition,
    popoverColor,
    flickColor,
    className,
    testId,
  } = usePopover();

  if (!isOpen) {
    return;
  }

  return (
    <div
      ref={ref}
      className={`swo-ds-popover ${styles[`popover__content--${cssPosition}`]} ${className || ''} ${
        styles[getFlickClassName(currentRelativePosition)] || ''
      }`}
      style={
        {
          ...position,
          minWidth,
          backgroundColor: popoverColor,
          '--popover-flick-color': flickColor,
          visibility: isPositionUpdated ? 'visible' : 'hidden',
        } as React.CSSProperties
      }
      data-testid={testId + '__content'}
    >
      {children}
    </div>
  );
});
