import { PropsWithChildren, Suspense, createContext, useContext, useMemo } from 'react';

import { LanguageCode, LocalisationProvider, getBrowserDefaults } from './localisation';
import { getIntlSeparators } from './localisation/helper/replaceSeparators';

export interface DesignSystemOptions {
  languageCode: LanguageCode;
  dateFormat: string | undefined;
  timeFormat: string | undefined;
  inputDateFormat: string | undefined;
  numberFormat: { decimalSeparator?: string; groupSeparator?: string } | undefined;
  timeZone: string | undefined;
  intlSeparators?: { decimal: string; group: string };
}

function getDefaultOptions(): DesignSystemOptions {
  try {
    const browserDefaults = getBrowserDefaults();
    return { ...browserDefaults, languageCode: 'en-US', inputDateFormat: browserDefaults.dateFormat };
  } catch {
    return {
      languageCode: 'en-US',
      dateFormat: 'M/d/yyyy',
      timeFormat: '12h',
      inputDateFormat: 'M/d/yyyy',
      numberFormat: { decimalSeparator: '.', groupSeparator: ',' },
      timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    };
  }
}

const DesignSystemOptionsContext = createContext<DesignSystemOptions>(getDefaultOptions());

export function useDesignSystemOptions() {
  return useContext(DesignSystemOptionsContext);
}

export interface DesignSystemOptionsProviderProps extends PropsWithChildren {
  value: Omit<Partial<DesignSystemOptions>, 'locale'>;
}

export function DesignSystemOptionsProvider({
  value: { languageCode, dateFormat, timeFormat, inputDateFormat, numberFormat, timeZone },
  children,
}: DesignSystemOptionsProviderProps) {
  const defaults = getDefaultOptions();
  const providerValue = useMemo(() => {
    const resolvedDateFormat = dateFormat ?? defaults.dateFormat;
    const resolvedLanguage = languageCode ?? defaults.languageCode;

    return {
      languageCode: resolvedLanguage,
      dateFormat: resolvedDateFormat,
      timeFormat: timeFormat ?? defaults.timeFormat,
      inputDateFormat: inputDateFormat ?? resolvedDateFormat,
      numberFormat: numberFormat ?? defaults.numberFormat,
      timeZone: timeZone ?? defaults.timeZone,
      intlSeparators: getIntlSeparators(resolvedLanguage),
    };
  }, [languageCode, dateFormat, timeFormat, inputDateFormat, numberFormat, timeZone, defaults]);

  return (
    <Suspense fallback={<></>}>
      <DesignSystemOptionsContext.Provider value={providerValue}>
        <LocalisationProvider languageCode={providerValue.languageCode}>{children}</LocalisationProvider>
      </DesignSystemOptionsContext.Provider>
    </Suspense>
  );
}

export function useBrowserDefaults() {
  return useMemo(() => {
    return getBrowserDefaults();
  }, []);
}
