import i18next, { InitOptions } from 'i18next';
import resourcesToBackend from 'i18next-resources-to-backend';

export const languageCodes = [
  'zh-CN',
  'zh-TW',
  'cs-CZ',
  'nl-NL',
  'en-GB',
  'en-US',
  'fi-FI',
  'fr-FR',
  'de-DE',
  'hu-HU',
  'it-IT',
  'ja-JP',
  'ko-KR',
  'nb-NO',
  'pl-PL',
  'ru-RU',
  'pt-PT',
  'es-ES',
  'sv-SE',
] as const;

export type LanguageCode = (typeof languageCodes)[number];

const i18n = i18next.createInstance();

i18n.use(
  resourcesToBackend((language, namespace, callback) => {
    const validLanguage = languageCodes.find(l => l.includes(language))?.replace('-', '_');
    if (!validLanguage) {
      callback(null, { [namespace]: {} });
      return;
    }

    const resource = language.startsWith('en')
      ? import(`./languages/en.json`)
      : import(`./languages/${validLanguage}/${validLanguage}.json`);

    resource
      .then(({ default: resources }) => {
        if (namespace === 'translation') {
          callback(null, resources);
          return;
        }
        callback(null, resources);
      })
      .catch(error => {
        callback(error, null);
      });
  })
);
i18n.on('failedLoading', (lng, _ns, msg) =>
  console.error(`[i18n] Failed to load design system language resource: ${lng}/${_ns}. Error:`, msg)
);
i18n.init({
  lng: 'en',
  fallbackLng: 'en',
  interpolation: {
    escapeValue: false,
  },
  defaultNS: 'ds',
} as InitOptions);

export { i18n };
