import type { LanguageCode } from '../i18n/translation';

export const languageCodeToDateFormatName = [
  { languageCode: 'zh-TW', dateFormatName: 'yyyy/M/d' },
  { languageCode: 'zh-CN', dateFormatName: 'yyyy/M/d' },
  { languageCode: 'nl-BE', dateFormatName: 'd/MM/yyyy' },
  { languageCode: 'nl-NL', dateFormatName: 'd-M-yyyy' },
  { languageCode: 'en-GB', dateFormatName: 'dd/MM/yyyy' },
  { languageCode: 'en-US', dateFormatName: 'M/d/yyyy' },
  { languageCode: 'fr-FR', dateFormatName: 'dd/MM/yyyy' },
  { languageCode: 'fr-CH', dateFormatName: 'dd.MM.yyyy' },
  { languageCode: 'de-CH', dateFormatName: 'dd.MM.yyyy' },
  { languageCode: 'de-DE', dateFormatName: 'dd.MM.yyyy' },
  { languageCode: 'hi-IN', dateFormatName: 'dd-MM-yyyy' },
  { languageCode: 'it-IT', dateFormatName: 'dd/MM/yyyy' },
  { languageCode: 'ja-JP', dateFormatName: 'yyyy/MM/dd' },
  { languageCode: 'pt-BR', dateFormatName: 'dd/MM/yyyy' },
  { languageCode: 'pt-PT', dateFormatName: 'dd/MM/yyyy' },
  { languageCode: 'es-AR', dateFormatName: 'd/M/yyyy' },
  { languageCode: 'es-CL', dateFormatName: 'dd-MM-yyyy' },
  { languageCode: 'es-MX', dateFormatName: 'dd/MM/yyyy' },
  { languageCode: 'es-PR', dateFormatName: 'MM/dd/yyyy' },
  { languageCode: 'es-ES', dateFormatName: 'dd/MM/yyyy' },
  { languageCode: 'sv-SE', dateFormatName: 'yyyy-MM-dd' },
] as { languageCode: LanguageCode; dateFormatName: string }[];

export function resolveDateFormatForLanguage(rawLang: string): string {
  const lang = rawLang || 'en-US';
  let found = languageCodeToDateFormatName.find(item => item.languageCode === lang);
  if (found) {
    return found.dateFormatName;
  }
  const baseLang = lang.split('-')[0];
  const preferredLang = `${baseLang}-${baseLang.toUpperCase()}`;
  found = languageCodeToDateFormatName.find(item => item.languageCode === preferredLang);
  if (found) {
    return found.dateFormatName;
  }
  found = languageCodeToDateFormatName.find(item => item.languageCode.startsWith(baseLang + '-'));
  if (found) {
    return found.dateFormatName;
  }
  return 'M/d/yyyy';
}
