import { useCallback, useState } from 'react';

const noop = () => undefined;

/**
 * A hook to handle open/close of a dropdown when trigger is click.
 * @param isOpenOutside open state as defined by the parent component
 * @param trigger trigger option. 'click' will cause the state to be managed internally, 'manual' will allow the state to be set externally.
 * @param isOpenChange callback function to be called when the dropdown is opened/closed
 * @returns
 */
export function useManualOpenHandler(
  isOpenOutside: boolean | undefined,
  trigger: 'manual' | 'click',
  isOpenChange?: (isOpenOutside: boolean) => void
): [boolean, (isOpenOutside: boolean) => void] {
  const [manualIsOpen, setManualIsOpen] = useState(false);

  const clickTriggerOpenHandle = useCallback(
    (isOpen: boolean) => {
      if (isOpen === manualIsOpen) {
        return;
      }
      setManualIsOpen(isOpen);
      isOpenChange?.(isOpen);
    },
    [isOpenChange, manualIsOpen]
  );

  if (trigger === 'click') {
    return [isOpenOutside ?? manualIsOpen, clickTriggerOpenHandle];
  }

  return [isOpenOutside ?? false, isOpenChange ?? noop];
}
