import styles from './Dropdown.module.scss';

import React, { JSX, useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { CssPosition, CustomRelativePosition, Popover } from '@swo/popover';

import { DropdownOption, DropdownOptionSingleOption } from './Dropdown.Option';
import { useHandleKeyboardItemSelection } from './hooks/useHandleKeyboardItemSelection';
import { useHandleKeyboardNavigation } from './hooks/useHandleKeyboardNavigation';
import { useHandleKeyboardSearch } from './hooks/useHandleKeyboardSearch';
import { useHandlePopoverStateChangesByTargetEvents } from './hooks/useHandlePopoverStateChangesByTargetEvents';
import { useKeyboardMode } from './hooks/useKeyboardMode';
import { useManualOpenHandler } from './hooks/useManualOpenHandler';
import { DropdownListOptionProps, ListDivider, ListGroup, ListItem, ListOption } from './types';

export interface DropdownListProps<T = string> {
  value: T | T[];
  options: ListOption<T>[];
  children: React.ReactNode;
  headerContent?: React.ReactNode;
  trigger?: 'click' | 'manual';
  popoverCssPosition?: CssPosition;
  positions?: CustomRelativePosition | Array<CustomRelativePosition>;
  isOpen?: boolean;
  isInput?: boolean;
  isToUseCustomSearch?: boolean;
  /**
   *
   * @param isOpen state of dropdown
   * @returns
   */
  isOpenChange?: (isOpen: boolean) => void;

  /**
   * Triggered whenever there's a different item selected
   * @param value selected item value
   * @returns
   */
  onItemSelected: (value: T) => void;
  /**
   * Triggered whenever there's a different item active.
   *
   * An active item is an item that's currently highlighted by the keyboard navigation.
   * @param value active item value
   * @returns
   */
  onItemActive?: (value: T | null) => void;
  /**
   * Triggered whenever there's a different item hovered.
   *
   * A hovered item is an item that's currently hovered by the mouse.
   * @param value hovered item value
   * @returns
   */
  onItemHover?: (value: T) => void;
  /**
   * A function that should return an element for rendering as a dropdown item.
   * It should also handle the divider and group rendering.
   * @param props Dropdown option props
   * @returns
   */
  itemElementRenderer?: (props: DropdownListOptionProps<T>) => JSX.Element;

  className?: string;
  testId?: string;
  maxHeight?: number;
  isToResetAfterClose?: boolean;
}

const defaultPositions: CustomRelativePosition[] = [{ position: 'bottom-start' }, { position: 'top-start' }];

export function Dropdown<T = string>({
  value,
  options,
  isOpen: isOpenOutside,
  isOpenChange: isOpenChangeOutside,
  trigger = 'click',
  popoverCssPosition = 'absolute',
  positions = defaultPositions,
  onItemSelected,
  onItemActive,
  onItemHover,
  itemElementRenderer = props => <DropdownOptionSingleOption {...props} />,
  testId = 'dropdown',
  maxHeight,
  className,
  children,
  headerContent,
  isToResetAfterClose = false,
  isInput = false,
  isToUseCustomSearch = false,
}: DropdownListProps<T>) {
  const menuRef = useRef<HTMLDivElement>(null);
  const targetRef = useRef<HTMLDivElement>(null);
  const [activeValue, setActiveValue] = useState<T | null>(null);
  const [isOpen, isOpenChange] = useManualOpenHandler(isOpenOutside, trigger, isOpenChangeOutside);
  const items = useMemo(() => options.filter(x => x && typeof x === 'object' && !('type' in x)) as ListItem<T>[], [options]);
  const isKeyboardMode = useKeyboardMode();

  const selectOption = useCallback(
    (item: ListItem<T> | undefined) => {
      const selectedOption = items.find(opt => opt.value === item?.value);
      if (!selectedOption) {
        return;
      }

      const selectedValue = selectedOption.value;
      setActiveValue(selectedValue);
      onItemActive?.(selectedValue);
      onItemSelected?.(selectedValue);

      isOpenChange?.(false);
    },
    [items, onItemActive, onItemSelected, isOpenChange]
  );

  useEffect(() => {
    if (!isOpen && isToResetAfterClose) {
      setActiveValue(null);
    }
  }, [isOpen, isToResetAfterClose]);

  const onSearch = useCallback(
    (searchTerm: string) => {
      if (!searchTerm) {
        return;
      }
      const foundItem = items.find(item => typeof item.label === 'string' && item.label.toLowerCase().startsWith(searchTerm));
      if (foundItem) {
        setActiveValue(foundItem.value);
        onItemActive?.(foundItem.value);
      }
      if (!isOpen) {
        selectOption(foundItem);
      }
    },
    [isOpen, items, onItemActive, selectOption]
  );

  const onActiveIndexChange = useCallback(
    (newActiveIndex: number) => {
      const currentActiveIndex = items.findIndex(x => x.value === activeValue);
      if (currentActiveIndex === newActiveIndex) {
        return;
      }

      const newValue = items[newActiveIndex]?.value ?? null;
      setActiveValue(newValue);
      onItemActive?.(newValue);
    },
    [activeValue, items, onItemActive]
  );

  const selectActiveItem = useCallback(() => selectOption(items.find(x => x.value === activeValue)), [activeValue, items, selectOption]);

  const currentActiveIndex = useMemo(() => items.findIndex(x => x.value === activeValue), [items, activeValue]);

  const navigationRef = isInput ? menuRef : targetRef;

  useHandleKeyboardNavigation(navigationRef, currentActiveIndex, items.length, onActiveIndexChange, isInput, isOpen);
  useHandlePopoverStateChangesByTargetEvents(targetRef, menuRef, trigger, isOpen, isOpenChange);
  useHandleKeyboardSearch(navigationRef, onSearch, isToUseCustomSearch);
  useHandleKeyboardItemSelection(navigationRef, selectActiveItem);

  const processedValue = useMemo(() => {
    if (value === null || value === undefined) {
      return [];
    }
    if (Array.isArray(value)) {
      return value;
    }
    return [value];
  }, [value]);

  return (
    <Popover
      trigger='manual'
      testId={testId + '__popover'}
      isOpen={isOpen}
      isOpenChange={isOpenChange}
      positions={positions}
      cssPosition={popoverCssPosition}
      className={className}
      isToSetMinWidth
    >
      <Popover.Target>
        <div ref={targetRef}>{children}</div>
      </Popover.Target>
      <Popover.Content>
        <div data-testid={testId} className={styles['dropdown-list']} ref={menuRef}>
          {headerContent}
          <ul role='listbox' style={maxHeight ? { maxHeight } : undefined}>
            {options.map((option, index) => (
              <DropdownOption<T>
                key={index}
                testId={testId + '-option-' + index}
                itemElementRenderer={itemElementRenderer}
                option={option}
                selectedValue={processedValue}
                activeValue={activeValue}
                onSelect={selectOption}
                onItemHover={onItemHover}
                isKeyboardMode={isKeyboardMode}
              />
            ))}
          </ul>
        </div>
      </Popover.Content>
    </Popover>
  );
}

export default Dropdown;

export function isListGroup(option: ListOption): option is ListGroup {
  return 'type' in option && option.type === 'group';
}

export function isListItem<T>(option: ListOption<T>): option is ListItem<T> {
  return 'value' in option;
}

export function isListDivider(option: ListOption): option is ListDivider {
  return 'type' in option && option.type === 'divider';
}
