import { useLayoutEffect, useState } from 'react';

interface Size {
  width: number;
  height: number;
}

function getInnerSize(el: HTMLElement): Size {
  const style = window.getComputedStyle(el);

  const paddingTop = parseFloat(style.paddingTop);
  const paddingBottom = parseFloat(style.paddingBottom);
  const paddingLeft = parseFloat(style.paddingLeft);
  const paddingRight = parseFloat(style.paddingRight);

  const width = el.clientWidth - paddingLeft - paddingRight;
  const height = el.clientHeight - paddingTop - paddingBottom;

  return { width, height };
}

export function useInnerSize(ref: React.RefObject<HTMLElement | null>): Size {
  const [size, setSize] = useState<Size>({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) {
      return;
    }

    const updateSize = () => {
      setSize(getInnerSize(el));
    };

    updateSize();

    const observer = new ResizeObserver(updateSize);
    observer.observe(el);

    return () => observer.disconnect();
  }, [ref]);

  return size;
}
