export function getNewIndex(index: number, length: number, event: KeyboardEvent) {
  const PAGE_SIZE = 5;

  switch (event.key) {
    case 'ArrowUp':
      return (length + index - 1) % length;
    case 'ArrowDown':
      if (event.altKey) {
        return index;
      }
      return (index + 1) % length;
    case 'PageUp':
      return Math.max(index - PAGE_SIZE, 0) % length;
    case 'PageDown':
      return Math.min(index + PAGE_SIZE, length - 1) % length;
    case 'Home':
      return 0;
    case 'End':
      return length - 1;
  }
  return index;
}
