import { formatInTimeZone } from 'date-fns-tz';
import { format } from 'date-fns/format';
import { useCallback, useMemo } from 'react';

import { useDesignSystemOptions } from '../../useDesignSystemOptions';
import { detectBrowserEnvironment } from '../helper/browserEnvironment';

export interface FormatTimeOptions {
  timeFormat?: string;
  timeZone?: string;
}

function resolveTimePattern(format?: string): string {
  switch (format) {
    case '12h':
      return 'hh:mm a';
    case '24h':
      return 'HH:mm';
    case 'HH:mm':
    case 'hh:mm a':
      return format;
    default:
      return 'HH:mm';
  }
}

export function formatTimeCore(date: string | Date | null | undefined, options?: FormatTimeOptions): string {
  if (date == null) {
    return '';
  }
  const value = date instanceof Date ? date : new Date(date);
  if (isNaN(value.getTime())) {
    return '';
  }
  const tz = options?.timeZone ?? Intl.DateTimeFormat().resolvedOptions().timeZone;
  const fmt = resolveTimePattern(options?.timeFormat);

  try {
    return formatInTimeZone(value, tz, fmt);
  } catch {
    try {
      return format(value, fmt);
    } catch {
      return format(value, 'HH:mm');
    }
  }
}

export function useFormatTime() {
  const { timeFormat, timeZone } = useDesignSystemOptions();
  return useFormatTimeInternal({ timeFormat, timeZone });
}

export function useFormatTimeInternal(options: FormatTimeOptions) {
  const { timeFormat: optTimeFormat, timeZone: optTimeZone } = options;
  const browserDefaults = useMemo(() => detectBrowserEnvironment(), []);

  const baseOptions = useMemo(() => {
    const timeFormat = optTimeFormat ?? browserDefaults.timeFormat;
    const timeZone = optTimeZone ?? browserDefaults.timeZone;
    return { timeFormat, timeZone };
  }, [optTimeFormat, optTimeZone, browserDefaults]);

  return useCallback(
    (date: string | Date | null | undefined, overrides?: FormatTimeOptions) => {
      return formatTimeCore(date, {
        timeFormat: overrides?.timeFormat ?? baseOptions.timeFormat,
        timeZone: overrides?.timeZone ?? baseOptions.timeZone,
      });
    },
    [baseOptions]
  );
}
