import { useEffect } from 'react';

/**
 * A hook to notify whenever there's a scroll event on the document.
 * @param isActive flag to indicate if the scroll listener should be active or not
 * @param ref ref to the element whose scroll should be ignored
 * @param onScroll callback to be called when any scroll happens
 */
export function useOnOutsideScroll(isActive: boolean, ref: React.RefObject<HTMLElement | null>, onScroll: () => void) {
  useEffect(() => {
    if (!isActive) {
      return;
    }

    function onScrollFn(evt: Event) {
      if (ref.current?.contains(evt.target as HTMLElement)) {
        return;
      }
      onScroll?.();
    }

    document.addEventListener('scroll', onScrollFn, true);

    return () => document.removeEventListener('scroll', onScrollFn, true);
  }, [onScroll, isActive, ref]);
}
