import { useCallback, useEffect, useMemo, useState } from 'react';

import { DropdownListProps } from '../Dropdown';
import { ListItem, ListOption } from '../types';

/**
 * Hook to setup a dropdown containing selectable items. It requires and tracks the selected item.
 * @param value selected value. If undefined, no item will be selected. Only a single value is supported.
 * @param options list of items to display on the dropdown menu
 * @param onChange callback function to be called when a different item is selected
 * @returns
 */
export function useDropdownSelect<T>(
  value: T | undefined,
  options: ListOption<T>[],
  onChange: (value: T) => void
): Omit<DropdownListProps<T>, 'children'> & { selectedItem?: ListItem<T> } {
  const [selectedValue, setSelectedValue] = useState<T | undefined>(value);

  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setSelectedValue(value);
  }, [value]);

  const isOpenChange = useCallback((newIsOpen: boolean) => {
    setIsOpen(newIsOpen);
  }, []);

  const onItemSelected = useCallback(
    (value: T) => {
      onChange(value);
      setSelectedValue(value);
    },
    [onChange]
  );

  const onItemActive = useCallback(
    (value: T | null) => {
      if (isOpen) {
        return;
      }

      if (!value) {
        return;
      }

      onItemSelected(value);
    },
    [isOpen, onItemSelected]
  );

  const selectedItem = useMemo(
    () => (options.filter(x => !('type' in x)) as ListItem<T>[]).find(o => o.value === selectedValue),
    [options, selectedValue]
  );

  return {
    options,
    value: selectedValue ?? [],
    selectedItem,
    onItemSelected,
    onItemActive,
    isOpenChange,
  };
}
