import styles from '../Tabs.module.scss';

import React, { Children, ComponentProps, ReactElement, ReactNode, useMemo } from 'react';

import { useTabs } from '../context/Tabs.Context';
import { TabDivider } from './Tab.Divider';
import { TabItem, isTabItem } from './Tab.Item';

export interface TabContentProps {
  children: ReactNode;
}

export function TabContent({ children }: TabContentProps) {
  return <>{children}</>;
}

TabContent.displayName = 'Tab.Content';

export interface TabContentPanelProps {
  tabItems: ReactElement<ComponentProps<typeof TabItem | typeof TabDivider>>[];
  type?: 'inline' | 'block';
}

export function TabContentPanel({ tabItems, type = 'block' }: TabContentPanelProps) {
  const { selectedTab, position } = useTabs();
  const selectedItem = tabItems.filter(isTabItem).find(item => item.props.id === selectedTab);

  const content = useMemo(() => {
    return Children.toArray(selectedItem?.props.children).find(
      child => React.isValidElement(child) && (child.type as React.FunctionComponent).displayName === 'Tab.Content'
    ) as ReactElement;
  }, [selectedItem]);

  const contentClassName = `${styles['tabs-content']} ${styles[`tabs-content--${type}`]} ${styles[`tabs-content--${position}`]}`;

  if (selectedItem) {
    return content ? (
      <div className={contentClassName} data-testid='tabs-content'>
        {content}
      </div>
    ) : (
      ''
    );
  }
  return '';
}
