/* eslint-disable react/button-has-type */
import styles from './Button.module.scss';

import React, { ReactElement, ReactNode, useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { SpinnerIsBusy } from './svg/SpinnerIsBusy';

type ButtonType = 'primary' | 'secondary' | 'text' | 'outline';

type ButtonColor = 'primary' | 'danger' | 'dark';

type HTMLButtonType = 'button' | 'submit' | 'reset';

interface ButtonProps {
  children: React.ReactNode;
  onClick?: (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => void;
  type?: ButtonType;
  color?: ButtonColor;
  isDisabled?: boolean;
  icon?: ReactNode;
  testId?: string;
  htmlType?: HTMLButtonType;
  className?: string;
  isBusy?: boolean;
}

const Button = React.forwardRef(
  (
    {
      children,
      onClick,
      type = 'primary',
      color = 'primary',
      isDisabled = false,
      icon,
      testId = 'button',
      htmlType = 'button',
      className = '',
      isBusy = false,
    }: ButtonProps,
    ref: React.Ref<HTMLButtonElement>
  ) => {
    const classNames = useMemo(() => {
      const bemClass = `button-${type}--${color}`;
      return `${styles.button} ${styles[bemClass]} ${className ? className : ''}`.trim();
    }, [type, color, className]);
    const containerRef = useRef<HTMLDivElement>(null);
    const [contentWidth, setContentWidth] = useState<React.CSSProperties>();

    useEffect(() => {
      if (containerRef.current?.offsetWidth && type === 'primary' && !isBusy) {
        setContentWidth({ width: `${containerRef.current?.offsetWidth}px` });
      }
    }, [type, isBusy, containerRef.current?.offsetWidth]);

    const onBtnClick = useCallback(
      (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
        if (isBusy) {
          return;
        }
        onClick?.(e);
      },
      [isBusy, onClick]
    );

    return (
      <button
        ref={ref}
        className={classNames}
        onClick={onBtnClick}
        disabled={isDisabled}
        data-isbusy={isBusy}
        data-testid={testId}
        type={htmlType}
      >
        {!!icon && (
          <span className={styles['button__icon']} data-testid={'button-icon'}>
            {icon}
          </span>
        )}
        <span className={styles['button__content']} ref={containerRef} style={isBusy ? contentWidth : {}}>
          {isBusy && type === 'primary' ? (
            <div className={`${styles['button__spinner']}`}>
              <SpinnerIsBusy />
            </div>
          ) : (
            children
          )}
        </span>
      </button>
    );
  }
);

Button.displayName = 'Button';

function isButton(el: ReactElement): el is ReactElement<ButtonProps> {
  if (el.type === Button) {
    return true;
  }

  if ((el.type as React.ComponentType)?.displayName === 'Button') {
    return true;
  }
  return false;
}

export { Button, ButtonProps, ButtonColor, HTMLButtonType, ButtonType, isButton };
