import { useEffect } from 'react';

/**
 * A hook to handle clicks outside of an element.
 * @param refs Reference to the element to check if the click was outside of it
 * @param onOutsideClick Callback to be called when there's a click outside of the element
 */
export function useHandleClickOutside(
  refs: React.RefObject<HTMLElement | null> | React.RefObject<HTMLElement | null>[],
  onOutsideClick: (e: MouseEvent) => void,
  isOpen: boolean
): void {
  useEffect(() => {
    if (!isOpen) {
      return;
    }

    const onMouseDown = (e: MouseEvent) => {
      if (!(e.target instanceof HTMLElement) && !(e.target instanceof SVGElement)) {
        return;
      }

      let refArray = refs;
      if (!Array.isArray(refArray)) {
        refArray = [refArray];
      }
      const elements = refArray.map(el => el?.current);

      if (!elements.some(Boolean)) {
        return;
      }

      const target = (e.composedPath?.() ?? [])[0] || e.target;

      if (!elements.some(el => el?.contains(target as HTMLElement))) {
        onOutsideClick(e);
      }
    };

    document.addEventListener('mousedown', onMouseDown);

    return () => document.removeEventListener('mousedown', onMouseDown);
  }, [refs, onOutsideClick, isOpen]);
}
