import { useEffect, useState } from 'react';

/**
 * A hook to notify when an element visibility changes in the viewport.
 * @param target element to observe for visibility
 * @param onChange callback to be called when the element visibility changes
 */
export function useIsVisible(target: React.RefObject<HTMLElement | null> | null | undefined) {
  const [isVisible, setIsVisible] = useState(false);
  useEffect(() => {
    if (!target?.current) {
      return;
    }

    if (!window['IntersectionObserver']) {
      setIsVisible(true);
      return;
    }

    const observer = new IntersectionObserver(onIntersection, {
      threshold: 0.1,
    });

    function onIntersection(entries: IntersectionObserverEntry[]) {
      const isVisible = entries.some(entry => entry.isIntersecting);
      setIsVisible(isVisible);
    }

    observer.observe(target.current as HTMLElement);

    return () => observer.disconnect();
  }, [target]);

  return isVisible;
}
