import styles from './Popover.module.scss';

import React, { ReactElement, ReactNode, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import { PopoverContent, PopoverInternalContent } from './Popover.Content';
import { PopoverContext } from './Popover.Context';
import { PopoverInternalTarget, PopoverTarget } from './Popover.Target';
import { useHandleClickOutside } from './hooks/useHandleOutsideClick';
import { useIsVisible } from './hooks/useIsVisible';
import { useOnOutsideScroll } from './hooks/useOnOutsideScroll';
import { useOnResize } from './hooks/useOnResize';
import { useTrigger } from './hooks/useTrigger';
import { CssPosition, CustomRelativePosition, PopoverTrigger, StylePosition } from './models';
import { calculatePosition } from './util/calculatePosition';

export interface PopoverProps {
  trigger?: PopoverTrigger;
  positions?: CustomRelativePosition | Array<CustomRelativePosition>;
  cssPosition?: CssPosition;
  children: ReactNode;
  isOpen?: boolean;
  keepOpenOnOutsideClick?: boolean;
  color?: string;
  flickColor?: string;
  testId?: string;
  isOpenChange?: (isOpen: boolean) => void;
  className?: string;
  isToSetMinWidth?: boolean;
  isToKeepOpenOnResize?: boolean;
  isToKeepOpenOnNotVisible?: boolean;
  portalElement?: HTMLElement;
}

const defaultPosition: CustomRelativePosition = { position: 'bottom-start', offset: { x: 0, y: 4 }, flick: 'none' };
export function Popover({
  trigger = 'click',
  positions,
  cssPosition = 'absolute',
  children,
  isOpen: isOpenManual,
  keepOpenOnOutsideClick,
  color = 'transparent',
  flickColor = color,
  testId = 'popover',
  isOpenChange,
  className,
  isToSetMinWidth,
  isToKeepOpenOnNotVisible = false,
  isToKeepOpenOnResize = false,
  portalElement,
}: PopoverProps) {
  const targetRef = useRef<HTMLDivElement | null>(null);
  const popoverRef = useRef<HTMLDivElement | null>(null);
  const isVisible = useIsVisible(targetRef);
  const [isOpen, setIsOpen] = useState(false);
  const [isPositionUpdated, setIsPositionUpdated] = useState(false);
  const [minWidth, setMinWidth] = useState<number | undefined>(undefined);
  const [position, setPosition] = useState<StylePosition>({ top: '0px', left: '0px' });
  const [currentRelativePosition, setCurrentRelativePosition] = useState<Required<CustomRelativePosition> | undefined>(undefined);

  const popoverTarget = React.Children.toArray(children).find(
    child => React.isValidElement(child) && (child.type as React.FunctionComponent).displayName === 'Popover.Target'
  ) as ReactElement;
  const popoverContent = React.Children.toArray(children).find(
    child => React.isValidElement(child) && (child.type as React.FunctionComponent).displayName === 'Popover.Content'
  ) as ReactElement;
  const processedPositions: Required<CustomRelativePosition>[] = useMemo(() => {
    if (positions instanceof Array) {
      positions.forEach(position => {
        position.flick = position.flick ?? 'none';
        position.offset = position.offset ?? { x: 0, y: 4 };
      });
      return positions as Required<CustomRelativePosition>[];
    }
    return [
      positions ? { ...positions, flick: positions.flick ?? 'none', offset: positions.offset ?? { x: 0, y: 4 } } : defaultPosition,
    ] as Required<CustomRelativePosition>[];
  }, [positions]);

  const open = useCallback(() => {
    if (isOpen) {
      return;
    }

    setIsOpen(true);
    isOpenChange?.(true);
    setIsPositionUpdated(false);
  }, [isOpen, isOpenChange]);

  const close = useCallback(() => {
    if (!isOpen) {
      return;
    }

    setIsOpen(false);
    isOpenChange?.(false);
  }, [isOpen, isOpenChange]);

  const updatePosition = useCallback(() => {
    const el = targetRef?.current?.childElementCount === 1 ? targetRef?.current?.firstElementChild : targetRef?.current;
    if (!el) {
      close();
      return;
    }
    const popover = popoverRef?.current;
    if (!popover) {
      close();
      return;
    }

    const { top, left, height: targetHeight, width: targetWidth } = el.getBoundingClientRect();

    const popoverHeight = popover.firstElementChild?.clientHeight ?? targetHeight;
    const popoverWidth = popover.firstElementChild?.clientWidth ?? targetWidth;

    const { stylePosition, relativePosition } = calculatePosition(
      { top, right: left + targetWidth, bottom: top + targetHeight, left, height: targetHeight, width: targetWidth },
      popoverHeight,
      popoverWidth,
      processedPositions,
      cssPosition
    );
    setPosition(stylePosition);
    setCurrentRelativePosition(relativePosition);
    setIsPositionUpdated(true);
  }, [targetRef, processedPositions, close, cssPosition]);

  useEffect(() => {
    updatePosition();
  }, [updatePosition]);

  useEffect(() => {
    if (isVisible || isToKeepOpenOnNotVisible) {
      return;
    }

    close();
  }, [isVisible, close, isToKeepOpenOnNotVisible]);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    if (!isToSetMinWidth) {
      setMinWidth(undefined);
      return;
    }

    setMinWidth(targetRef?.current?.firstElementChild?.clientWidth);
  }, [isOpen, isToSetMinWidth, targetRef]);

  useEffect(() => {
    if (trigger !== 'manual' && trigger !== 'click-manual') {
      return;
    }

    setIsOpen(!!isOpenManual);
    setIsPositionUpdated(false);
    updatePosition();
  }, [isOpenManual, trigger, updatePosition]);

  const onTrigger = useCallback(
    (triggerOpen?: boolean) => {
      if (!isVisible) {
        return;
      }

      updatePosition();

      if (triggerOpen !== undefined) {
        if (triggerOpen) {
          open();
        } else {
          close();
        }
        return;
      }

      if (isOpen) {
        close();
      } else {
        open();
      }
    },
    [isVisible, updatePosition, isOpen, open, close]
  );

  const onOutsideClick = useCallback(
    (e: MouseEvent) => {
      if (keepOpenOnOutsideClick) {
        return;
      }

      if (targetRef?.current?.contains(e.target as HTMLElement) && (trigger === 'click' || trigger === 'click-manual')) {
        return;
      }

      close();
    },
    [keepOpenOnOutsideClick, targetRef, trigger, close]
  );

  useHandleClickOutside([targetRef, popoverRef], onOutsideClick, isOpen);
  useTrigger(targetRef, trigger, onTrigger, popoverRef);
  useOnOutsideScroll(isOpen, popoverRef, cssPosition === 'fixed' ? close : updatePosition);
  useOnResize(isOpen, isToKeepOpenOnResize ? updatePosition : close);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    if (!('ResizeObserver' in window)) {
      return;
    }

    const obs = new ResizeObserver(() => {
      updatePosition();
    });

    if (popoverRef.current) {
      obs.observe(popoverRef.current);
    }

    return () => obs.disconnect();
  }, [isOpen, updatePosition]);

  const value = useMemo(
    () => ({
      isOpen,
      isPositionUpdated,
      minWidth,
      position,
      cssPosition,
      currentRelativePosition,
      popoverColor: color,
      flickColor,
      className,
      testId,
    }),
    [className, color, cssPosition, currentRelativePosition, flickColor, isOpen, isPositionUpdated, minWidth, position, testId]
  );

  const internalContent = <PopoverInternalContent ref={popoverRef}>{popoverContent}</PopoverInternalContent>;

  return (
    <PopoverContext.Provider value={value}>
      <div className={styles['popover__container']} data-testid={testId}>
        <PopoverInternalTarget ref={targetRef}>{popoverTarget}</PopoverInternalTarget>
        {cssPosition === 'fixed' && portalElement ? createPortal(internalContent, portalElement) : internalContent}
      </div>
    </PopoverContext.Provider>
  );
}

Popover.Content = PopoverContent;
Popover.Target = PopoverTarget;
