import { useCallback, useEffect } from 'react';

/**
 * A hook to handle keyboard item selection on a dropdown menu.
 *
 * Expects that the target element is focusable and will have the focus when the keyboard event is triggered.
 * @param target target element. Element that has triggered the dropdown to open/close
 * @param selectActiveOption callback function to be called when an action is selected due to keyboard intraction
 */
export function useHandleKeyboardItemSelection(target: React.RefObject<HTMLElement | null>, selectActiveOption: () => void) {
  const onKeyDown = useCallback(
    (e: KeyboardEvent) => {
      switch (e.key) {
        case 'Enter':
          selectActiveOption();
          return;
      }
    },
    [selectActiveOption]
  );

  useEffect(() => {
    const tgt = target?.current;
    tgt?.addEventListener('keydown', onKeyDown);
    return () => {
      tgt?.removeEventListener('keydown', onKeyDown);
    };
  }, [onKeyDown, target]);
}
