import { JSX, useCallback, useState } from 'react';

import { DropdownListOptionProps, ListItem } from '../types';

export function DropdownOption<T>({
  itemElementRenderer,
  onItemHover,
  isKeyboardMode,
  testId = 'dropdown-option',
  ...props
}: {
  onItemHover?: (value: T) => void;
  itemElementRenderer: (props: DropdownListOptionProps<T>) => JSX.Element;
  isKeyboardMode: boolean | undefined;
  testId?: string;
} & Omit<DropdownListOptionProps<T>, 'onHover'>) {
  const [hoverValue, setHoverValue] = useState<T | null>(null);

  const onHover = useCallback(
    (option: ListItem<T>) => {
      if (option.value === hoverValue) {
        return;
      }
      onItemHover?.(option.value);
      setHoverValue(option.value);
    },
    [hoverValue, onItemHover]
  );
  return itemElementRenderer({
    ...props,
    testId,
    onHover,
    isKeyboardMode,
  });
}
