import styles from '../Tabs.module.scss';

import React, { useMemo } from 'react';

export interface TabDividerProps {
  className?: string;
  testId?: string;
  position?: 'top' | 'bottom';
}

export const TabDivider: React.FC<TabDividerProps> = ({ className = '', testId = 'tab-divider' }) => {
  const dividerClassName = useMemo(() => {
    const classes = [styles['tab-divider']];

    if (className) {
      classes.push(className);
    }

    return classes.join(' ');
  }, [className]);

  return (
    <div className={dividerClassName} data-testid={testId} role='separator'>
      <span className={styles['tab-divider__line']}></span>
    </div>
  );
};

TabDivider.displayName = 'Tab.Divider';
