import { useCallback, useEffect, useEffectEvent, useState } from 'react';

/**
 * A hook to handle open/close state changes on a dropdown.
 *
 * Expects that the target element is focusable and will have the focus when the keyboard event is triggered.
 * @param target target element. Element that has triggered the dropdown to open/close
 * @param menuRef menu element. Element that contains the dropdown
 * @param trigger trigger option. 'click' will toggle the dropdown on click, 'manual' will only open/close the dropdown when the open state is set to true/false
 * @param isOpenOutside open state as controlled externally/programmatically.
 * @param onOpen callback function to be called when the dropdown is opened
 * @param onClose callback function to be called when the dropdown is closed
 */
export function useHandlePopoverStateChangesByTargetEvents(
  target: React.RefObject<HTMLElement | null>,
  menuRef: React.RefObject<HTMLDivElement | null>,
  trigger: 'click' | 'manual',
  isOpenOutside: boolean | undefined,
  isOpenChange: (isOpen: boolean) => void
) {
  const [isOpen, setIsOpen] = useState(false);

  const open = useCallback(() => {
    setIsOpen(true);
    isOpenChange?.(true);
  }, [isOpenChange]);
  const close = useCallback(() => {
    setIsOpen(false);
    isOpenChange?.(false);
  }, [isOpenChange]);

  useEffect(() => setIsOpen(isOpenOutside ?? false), [isOpenOutside]);

  const onBlur = useEffectEvent((e: FocusEvent) => {
    const relatedTarget = e.relatedTarget as HTMLElement;
    if (menuRef.current?.contains(relatedTarget)) {
      return;
    }

    const tgt = target?.current;
    if (tgt?.contains(relatedTarget)) {
      return;
    }

    close();
  });

  const onKeyDown = useCallback(
    (e: KeyboardEvent) => {
      switch (e.key) {
        case 'ArrowDown': {
          if (e.altKey) {
            open();
            return;
          }
          break;
        }
        case 'Enter':
          if (!isOpen) {
            open();
            return;
          }
          return;
        case 'Escape':
          if (isOpen) {
            close();
          }
          return;
      }
    },
    [close, isOpen, open]
  );

  const onClick = useCallback(() => {
    if (isOpen) {
      close();
    } else {
      open();
    }
  }, [close, isOpen, open]);

  useEffect(() => {
    const tgt = target?.current;
    tgt?.addEventListener('keydown', onKeyDown);
    if (trigger === 'click') {
      tgt?.addEventListener('click', onClick);
    }
    tgt?.addEventListener('blur', onBlur);
    return () => {
      tgt?.removeEventListener('keydown', onKeyDown);
      tgt?.removeEventListener('click', onClick);
      tgt?.removeEventListener('blur', onBlur);
    };
  }, [isOpen, onClick, onKeyDown, target, trigger]);
}
