import styles from './Tab.module.scss';

import { useCallback } from 'react';

import { Icon, IconName } from '@swo/icon';

export interface TabProps {
  title?: string;
  count?: number;
  isSelected?: boolean;
  isDisabled?: boolean;
  onClick: (e?: React.MouseEvent) => void;
  testId?: string;
  position?: 'top' | 'bottom';
  icon?: IconName;
}

export function Tab({ title, count, isSelected, isDisabled, onClick, testId = 'tab', position, icon }: TabProps) {
  const getClassName = useCallback(
    (baseClass: string) => {
      if (isDisabled) {
        return styles[`${baseClass}--disabled`];
      } else if (isSelected) {
        return styles[`${baseClass}--selected`];
      }
    },
    [isDisabled, isSelected]
  );

  return (
    <button
      type='button'
      className={`${styles['tab-wrapper']}  ${styles[`tab-wrapper--${position}`]} ${isSelected && !isDisabled ? `${styles[`tab__active`]} ${styles[`tab__active--${position}`]}` : ''}`}
      disabled={isDisabled}
      data-testid={testId}
      tabIndex={0}
      onClick={onClick}
    >
      <div className={`${styles['tab']} ${getClassName('tab')}`}>
        {!!count && count > 0 && (
          <div className={`${styles['tab__count']} ${getClassName('tab__count')}`}>
            <span>{count}</span>
          </div>
        )}
        {title && title}
        {icon && <Icon name={icon} size={24} />}
      </div>
    </button>
  );
}
