import React, { Children, ReactElement, isValidElement, useCallback, useMemo } from 'react';

import { Button, ButtonProps } from '@swo/button';
import { Dropdown, ListItem, useDropdownMenu } from '@swo/dropdown';
import { Icon } from '@swo/icon';

interface TabActionDropdownProps {
  actionItems: ReactElement<ButtonProps>[];
}

function buttonToListItem(actionItem: ReactElement<ButtonProps>): ListItem<ButtonProps> {
  return {
    label: typeof actionItem.props.children === 'string' ? actionItem.props.children : '',
    value: actionItem.props,
  };
}

export function TabActionDropdown({ actionItems }: TabActionDropdownProps) {
  const actions = useMemo(() => {
    return Children.toArray(actionItems)
      .filter(isValidElement<ButtonProps>)
      .map(buttonToListItem);
  }, [actionItems]);

  const onDropdownSelect = useCallback((selectedItem: ButtonProps) => {
    if (typeof selectedItem.onClick === 'function') {
      selectedItem.onClick?.(undefined as unknown as React.MouseEvent<HTMLButtonElement, MouseEvent>);
    }
  }, []);

  const dropdownProps = useDropdownMenu<ButtonProps>(actions, onDropdownSelect);

  return (
    <div>
      <Dropdown {...dropdownProps} positions={[{ position: 'bottom-end' }, { position: 'top-end' }]} isToResetAfterClose={true}>
        <Button type='secondary'>
          <Icon name='expand_more' type='outlined' size={24} color='black' transform='undefined' />
        </Button>
      </Dropdown>
    </div>
  );
}
