import { useCallback, useEffect } from 'react';

import { getNewIndex } from '../dropdownUtils';

export const navigationKeysUsedWhenClosed = ['ArrowUp', 'ArrowDown', 'Enter'];
export const navigationKeysNotUsedWhenClosed = ['PageUp', 'PageDown', 'Home', 'End', ' ', 'Escape'];
export const inputNavigationUsedKeys = ['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Enter', 'Escape'];
export const navigationKeys = ['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End', ' ', 'Enter', 'Escape'];

/**
 * A hook to handle keyboard navigation on a dropdown.
 *
 * Expects that the target element is focusable and will have the focus when the keyboard event is triggered.
 * @param target target element. Element that has triggered the dropdown to open/close
 * @param currentIndex index of the active element.
 * @param length size of the list
 * @param onActiveIndexChange callback to be called when the active index changes due to keyboard interaction
 */
export function useHandleKeyboardNavigation(
  target: React.RefObject<HTMLElement | null>,
  currentIndex: number,
  length: number,
  onActiveIndexChange: (newActiveIndex: number) => void,
  isInput: boolean,
  isOpen: boolean
) {
  const onKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (!isOpen) {
        if (navigationKeysUsedWhenClosed.includes(e.key)) {
          e.preventDefault();
        } else if (navigationKeysNotUsedWhenClosed.includes(e.key)) {
          return;
        }
      } else if (!isInput && navigationKeys.includes(e.key)) {
        e.preventDefault();
      }

      if (isInput && !inputNavigationUsedKeys.includes(e.key)) {
        return;
      }

      if (currentIndex === -1) {
        onActiveIndexChange(0);
        return;
      }

      const newActiveIndex = getNewIndex(currentIndex, length, e);

      onActiveIndexChange(newActiveIndex);
    },
    [currentIndex, isInput, isOpen, length, onActiveIndexChange]
  );

  useEffect(() => {
    const tgt = target?.current;
    tgt?.addEventListener('keydown', onKeyDown);
    return () => {
      tgt?.removeEventListener('keydown', onKeyDown);
    };
  }, [onKeyDown, target]);
}
